from collections import deque

def levels(graph, start):
    seen, queue, result = {start}, deque([start]), []
    while queue:
        ring = []
        for _ in range(len(queue)):
            node = queue.popleft()
            ring.append(node)
            for nb in graph[node]:
                if nb not in seen:
                    seen.add(nb)
                    queue.append(nb)
        result.append(ring)
    return result

g = {"A": ["B", "C"], "B": ["A", "D"], "C": ["A", "D"], "D": ["B", "C", "E"], "E": ["D"]}
print(levels(g, "A"))
```
This ring-at-a-time loop is the shape of multi-source problems such as NeetCode's "Rotting Oranges": put every source in the queue first, then count rounds.

