class Cycle:
    def __init__(self, seq, times):
        self.seq, self.times = seq, times
        self.rep, self.i = 0, 0
    def __iter__(self):
        return self
    def __next__(self):
        if not self.seq or self.rep >= self.times:
            raise StopIteration
        value = self.seq[self.i]
        self.i += 1
        if self.i == len(self.seq):
            self.i, self.rep = 0, self.rep + 1
        return value

print(list(Cycle("ab", 3)))
```

