from itertools import islice

def parse_scores(lines):
    for line in lines:
        line = line.strip()
        if not line or "," not in line:
            continue
        sid, raw = line.split(",", 1)
        try:
            score = int(raw)
        except ValueError:
            continue
        if 0 <= score <= 100:
            yield sid, score

def top_scores(lines, n):
    good = (r for r in parse_scores(lines) if r[1] >= 80)
    return list(islice(good, n))

data = ["S1,85", "", "S2,x", "S3,120", "S4,90", "S5,99"]
print(list(parse_scores(data)), top_scores(data, 2))
