import numpy as np

def rot(theta):
    c, s = np.cos(theta), np.sin(theta)
    return np.array([[c, -s], [s, c]])

def to_world(p_robot, pose):
    x, y, theta = pose
    return rot(theta) @ np.asarray(p_robot, float) + np.array([x, y])

def to_robot(p_world, pose):
    x, y, theta = pose
    return rot(theta).T @ (np.asarray(p_world, float) - np.array([x, y]))

print(to_world((3, 0), (2, 1, np.pi / 2)), to_robot((2, 4), (2, 1, np.pi / 2)))
```

